import networkx as nx
G = nx.Graph()
for i in range(24):
    G.add_node(i)
for i in range(24):
    for j in range(i+1, 24):
        if (i // 4 == j // 4) or (i % 4 == j % 4):
            G.add_edge(i, j)
girth = nx.girth(G)
if girth >= 7:
    print("SATISFIABLE")
    print(list(G.edges))
else:
    print("UNSATISFIABLE")
